"""Generated by integrations/semantic_bridge/synthesis.py -- a real,
two-dimensional aggregate over a recruited query, grouping by "holder"
then "status", counting distinct "account" refs. Read-only: no
world mutation, so no operations.py dispatch branch is needed -- this
Capability is invoked, never committed.
"""
import json

from hostio import fail
from semanticworld.interpretation.projection_value import validate
from semanticworld.read import recruit
from semanticworld.reference import plain


def propose(projection, *, read, demand):
    projection = validate(read, projection)
    selected = recruit(read, plain(projection.request), result_bound=projection.result_bound,
        work_bound=projection.work_bound)
    if not selected.complete:
        fail('INVALID_REQUEST', 'Exposure aggregation requires complete recruited context')
    types = {node.ref: node.node_type for node in selected.instances.nodes}
    buckets = {}
    for row in selected.result['evidence']['rows']:
        assignment = dict(row['assignment'])
        outer_key = assignment['holder']
        inner_key = types.get(assignment['status'], assignment['status'])
        count_ref = assignment['account']
        buckets.setdefault(outer_key, {}).setdefault(inner_key, set()).add(count_ref)
    report = {outer_key: {inner_key: len(refs) for inner_key, refs in by_inner.items()}
        for outer_key, by_inner in buckets.items()}
    return json.dumps(report, sort_keys=True)
